UPDATE CRM_EMP_MGT
SET
     PASS = #{pass, jdbcType=VARCHAR}
 WHERE 
     EMP_NO = #{emp_no, jdbcType=VARCHAR} 
 AND
     EMP_NM = #{emp_nm, jdbcType=VARCHAR}
 AND 
     E_MAIL = #{e_mail, jdbcType=VARCHAR}


UPDATE CRM_CUST_ERP
SET
     USE_TYPE = #{use_type}
 WHERE 
     EMP_ID = #{emp_id, jdbcType=VARCHAR}
